(()=>{'use strict';const F=MartinsFluxos,J=MartinsJornada,P=MartinsPersistenciaRdo,$=id=>document.getElementById(id);
const css=document.createElement('style');css.textContent='#mj-open{display:none!important}#martins-bottom-bar>div{display:grid!important;grid-template-columns:repeat(7,minmax(0,1fr));align-items:stretch;gap:0!important}#martins-bottom-bar button{display:flex!important;flex-direction:column;justify-content:center!important;align-items:center!important;min-width:0!important;width:100%;min-height:56px;margin:0!important;gap:4px;line-height:1.1}#martins-bottom-bar button>span{margin-top:0!important;text-align:center;white-space:nowrap;font-size:9px!important}#bnav-btn-menu>div{width:20px!important;height:20px!important;border-radius:5px!important}#bnav-btn-menu svg{width:17px;height:17px}.mf-date{display:inline-flex;position:relative;align-items:center;max-width:100%;width:190px;vertical-align:middle}.mf-date-text{width:100%!important;padding-right:42px!important;box-sizing:border-box}.mf-date-native{position:absolute!important;right:0!important;top:0!important;width:40px!important;height:100%!important;opacity:0!important;cursor:pointer}.mf-calendar{position:absolute;right:10px;pointer-events:none;color:#475569;font-size:20px}.mf-near-status{font-size:12px;padding:8px;color:#92400e;white-space:pre-wrap}.mf-client-action{padding:8px 10px;margin:5px;background:#0f172a;color:#fbbf24;border-radius:8px;font-size:12px;min-height:40px}.mpdf-logo{display:block;max-width:160px;max-height:80px;object-fit:contain;margin:0 auto 12px}.mpdf-download{display:inline-block;padding:12px;background:#0f172a;color:#fbbf24;border-radius:8px;margin:8px;font-size:12px}';document.head.append(css);
function dateInput(input){if(input.dataset.mfDate)return;input.dataset.mfDate='1';input.lang='pt-BR';const wrap=document.createElement('span');wrap.className='mf-date';const text=document.createElement('input');text.type='text';text.inputMode='numeric';text.placeholder='dd/mm/aaaa';text.id='br-'+(input.id||P.newId());text.className=input.className+' mf-date-text';text.setAttribute('aria-label',(input.getAttribute('aria-label')||input.closest('label')?.textContent.trim()||input.id||'Data')+' (dd/mm/aaaa)');text.required=input.required;text.disabled=input.disabled;text.readOnly=input.readOnly;const icon=document.createElement('span');icon.className='mf-calendar';icon.textContent='▦';icon.setAttribute('aria-hidden','true');input.before(wrap);wrap.append(text,icon,input);input.classList.add('mf-date-native');input.title='Abrir calendário';input.setAttribute('aria-label','Abrir calendário da data');const desc=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');const sync=()=>{try{text.value=F.br(desc.get.call(input));text.setCustomValidity('');}catch{text.value='';}};Object.defineProperty(input,'value',{configurable:true,get(){return desc.get.call(this);},set(v){desc.set.call(this,v);sync();}});input.addEventListener('input',sync);input.addEventListener('change',sync);text.addEventListener('input',()=>{text.setCustomValidity('');});text.addEventListener('change',()=>{const raw=text.value;try{input.value=raw.trim()?F.iso(raw):'';text.setCustomValidity('');}catch(e){input.value='';text.value=raw;text.setCustomValidity(e.message);text.reportValidity();return;}input.dispatchEvent(new Event('change',{bubbles:true}));});input.addEventListener('click',()=>{try{input.showPicker?.();}catch{}});input.form?.addEventListener('reset',()=>setTimeout(sync,0));sync();}
function dates(){for(const input of document.querySelectorAll('input[type=date]'))dateInput(input);}window.martinsFormatarDatas=dates;
// Algumas versões da fonte não continham o formulário referenciado pelos atalhos de clientes.
if(!$('modal-novo-cliente-rapido')){const modal=document.createElement('div');modal.id='modal-novo-cliente-rapido';modal.className='hidden no-print';modal.style.cssText='position:fixed;inset:0;background:#020617bb;align-items:center;justify-content:center;padding:12px';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.setAttribute('aria-labelledby','mf-client-title');modal.innerHTML='<div style="background:white;border-radius:14px;padding:20px;width:min(600px,100%);box-sizing:border-box"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h3 id="mf-client-title" style="font-weight:800">Cadastrar cliente</h3><button type="button" aria-label="Fechar cadastro de cliente" onclick="document.getElementById(\'modal-novo-cliente-rapido\').classList.add(\'hidden\')">× Fechar</button></div><p style="font-size:12px;margin:12px 0">CPF/CNPJ é opcional. Quando informado, validamos o formato e os dígitos, sem consultar a situação cadastral na Receita. Cadastros antigos permanecem preservados.</p><form id="form-novo-cliente-rapido" class="mf-grid"><label>Nome / razão social<input id="cli-inp-nome" required maxlength="200" style="width:100%;padding:10px;border:1px solid #cbd5e1"></label><label>CPF/CNPJ<input id="cli-inp-doc" maxlength="100" style="width:100%;padding:10px;border:1px solid #cbd5e1"></label><label>Telefone<input id="cli-inp-tel" maxlength="100" style="width:100%;padding:10px;border:1px solid #cbd5e1"></label><label>Cidade<input id="cli-inp-cidade" maxlength="200" style="width:100%;padding:10px;border:1px solid #cbd5e1"></label><label>Observações<textarea id="cli-inp-obs" maxlength="2000" style="width:100%;padding:10px;border:1px solid #cbd5e1"></textarea></label><button type="submit" style="min-height:44px;padding:10px;background:#0f172a;color:#fbbf24;border-radius:8px">Salvar cliente</button><p id="mf-client-status" role="status" style="font-size:12px;color:#92400e"></p></form></div>';document.body.append(modal);$('form-novo-cliente-rapido').onsubmit=e=>window.salvarNovoClienteRapidoForm(e);}
function closeModal(id){const m=$(id);if(m){m.classList.add('hidden');m.style.display='none';for(const a of m.querySelectorAll('.mpdf-download'))a.remove();}}
function wireModal(id,z){const m=$(id);if(!m)return;m.style.zIndex=String(z);if(m.firstElementChild){m.firstElementChild.style.maxHeight='88vh';m.firstElementChild.style.overflowY='auto';}for(const b of m.querySelectorAll('button[onclick]'))if(b.getAttribute('onclick').includes("classList.add('hidden')"))b.onclick=()=>closeModal(id);m.onclick=e=>{if(e.target===m)closeModal(id);};}
const modals=['modal-sucesso-orcamento','modal-importar-nfe','modal-novo-cliente-rapido'];modals.forEach((id,i)=>wireModal(id,10080+i));document.addEventListener('keydown',e=>{if(e.key==='Escape'){const id=modals.slice().reverse().find(id=>$(id)&&!$(id).classList.contains('hidden')&&$(id).style.display!=='none');if(id){closeModal(id);e.preventDefault();e.stopImmediatePropagation();}}},true);window.fecharModalNovoClienteRapido=()=>closeModal('modal-novo-cliente-rapido');
function clean(){const chips=$('ponto-top3-usuarios-chips');chips?.closest('#subview-ponto-colab > div')?.remove();const b=$('ma-menu-rdo');if(b){const s=b.querySelector('span');if(s)s.textContent='Preencher RDO';b.title='Formulário do RDO: atividades, equipe, ocorrências e fotos';}}
const drawer=window.reorganizarDrawerLateralDefinitivo;if(typeof drawer==='function')window.reorganizarDrawerLateralDefinitivo=function(...args){const r=drawer.apply(this,args);clean();return r;};
// Cadastro/edição de clientes na mesma base existente, sem alterar documentos históricos.
function clientActor(){let session;try{session=JSON.parse(sessionStorage.getItem('cm_active_user')||'null');}catch{}const u=currentLoggedUser,id=x=>String(x?.id||x?.usuario||x?.email||'');if(!MartinsVendasObras.canSell(u)||!session||!id(u)||id(u)!==id(session)||u.perfil!==session.perfil||session.status==='Inativo')throw Error('Entre com perfil autorizado ao Comercial para alterar clientes');return u.usuario||u.email||u.nome;}
if(typeof CLIENTES_PADRAO==='undefined')window.CLIENTES_PADRAO=[];
const CK='cm_clientes_db';let editing=null,clientSnapshot=null,origin='orcamento',oldName='';window.getClientesDb=()=>J.read(localStorage,CK,CLIENTES_PADRAO);window.saveClientesDb=rows=>{J.write(localStorage,CK,rows,localStorage.getItem(CK));window.popularSelectClientesNoOrcamento?.();};
function openClient(edit=false,where='orcamento',clientId=null){try{clientActor();origin=where;clientSnapshot=localStorage.getItem(CK);const rows=window.getClientesDb();const selected=where==='obra'?$('obra-inp-cliente-select')?.value:$('orc-select-cliente-cadastrado')?.value||$('orc-inp-cliente')?.value;const matches=clientId?rows.filter(c=>c.id===clientId):rows.filter(c=>c.nome===selected);if(clientId&&matches.length!==1)throw Error('Cliente não encontrado ou com identificação duplicada');if(edit&&matches.length>1)throw Error('Cliente ambíguo; selecione cadastro único');const c=edit?matches[0]:null;editing=c?.id||null;oldName=c?.nome||selected||'';$('form-novo-cliente-rapido').reset();if($('mf-client-status'))$('mf-client-status').textContent=c?.doc&&!F.validDocument(c.doc)?'Documento antigo pendente de conferência. Será preservado se não for alterado.':'';for(const [id,key] of [['cli-inp-nome','nome'],['cli-inp-doc','doc'],['cli-inp-tel','tel'],['cli-inp-cidade','cidade'],['cli-inp-obs','obs']])$(id).value=c?.[key]||(edit&&key==='nome'?selected||'':'');const h=$('modal-novo-cliente-rapido').querySelector('h3');if(h)h.textContent=edit?'Editar cliente':'Cadastrar cliente';const modal=$('modal-novo-cliente-rapido');modal.classList.remove('hidden');modal.style.display='flex';$('cli-inp-nome').focus();}catch(e){showToast(e.message,'warning');}}
window.martinsAbrirClientePorId=id=>openClient(true,'cadastro',id);window.martinsNovoCliente=()=>openClient(false,'cadastro');window.abrirModalNovoClienteRapido=()=>openClient(false);window.editarClienteCadastrado=()=>openClient(true,'obra');window.salvarNovoClienteRapidoForm=function(event){event?.preventDefault();try{clientActor();const current=localStorage.getItem(CK);if(current!==clientSnapshot)throw Error('Cadastro alterado em outra aba. Reabra o cliente antes de salvar.');const result=F.saveClient(window.getClientesDb(),Object.fromEntries([['nome','cli-inp-nome'],['doc','cli-inp-doc'],['tel','cli-inp-tel'],['cidade','cli-inp-cidade'],['obs','cli-inp-obs']].map(([k,id])=>[k,$(id).value])),editing,'CLI-'+P.newId());J.write(localStorage,CK,result.rows,current);const selectedBefore=Object.fromEntries(['orc-select-cliente-cadastrado','obra-inp-cliente-select'].map(id=>[id,$(id)?.value]));window.popularSelectClientesNoOrcamento?.();for(const id of ['orc-select-cliente-cadastrado','obra-inp-cliente-select']){const s=$(id);if(!s)continue;for(const c of result.rows)if(![...s.options].some(o=>o.value===c.nome))s.add(new Option(c.nome,c.nome));if((origin==='obra'&&id==='obra-inp-cliente-select')||(origin==='orcamento'&&id==='orc-select-cliente-cadastrado')||(editing&&selectedBefore[id]===oldName))s.value=result.client.nome;}if((origin==='orcamento'||(editing&&$('orc-inp-cliente')?.value===oldName))&&$('orc-inp-cliente'))$('orc-inp-cliente').value=result.client.nome;if(origin==='obra'){$('display-nome-cliente-card').textContent=result.client.nome;const payer=$('obra-inp-quem-paga');if(payer&&(payer.value===oldName||!payer.value))payer.value=result.client.nome;}closeModal('modal-novo-cliente-rapido');window.dispatchEvent(new Event('martins-clientes-atualizados'));showToast('Cliente '+(editing?'atualizado':'cadastrado')+'. Documentos anteriores preservados.');}catch(e){if($('mf-client-status'))$('mf-client-status').textContent=e.message;showToast('Cliente não confirmado: '+e.message,'warning');}};
function clientActions(){const box=$('accordion-dados-cliente');if(box){for(const b of box.querySelectorAll('button')){const t=b.textContent.trim();if(t.includes('Novo cliente'))b.onclick=()=>openClient(false,'obra');if(t.includes('Editar cliente'))b.onclick=()=>openClient(true,'obra');if(t.includes('Atualizar dados'))b.onclick=()=>{$('display-nome-cliente-card').textContent=$('obra-inp-cliente-select').value;};}}const s=$('orc-select-cliente-cadastrado');if(s&&!$('mf-client-quick')){const b=document.createElement('button');b.type='button';b.id='mf-client-quick';b.className='mf-client-action';b.textContent='+ Cadastrar cliente';b.onclick=()=>openClient(false,'orcamento');s.after(b);const e=b.cloneNode();e.id='mf-client-edit';e.textContent='Editar cliente selecionado';e.onclick=()=>openClient(true,'orcamento');b.after(e);}}
// Auditoria: opções derivadas de cadastros e histórico, sem apagar ou reclassificar logs.
const modules=['RDO','Frequência','Planejamento','Gestão','Comercial','Vendas','Compras','Almoxarifado','Estoque','Financeiro','Medições','Fiscal','Clientes','Veículos','Uniformes','EPI','Relatórios','Acessos','Configurações','Produção','Orçamentos','Notas Fiscais','Produtos','Calendário','Auditoria','Documentos','Suprimentos'];
function options(id,items,first){const s=$(id);if(!s)return;const old=s.value;s.replaceChildren(new Option(first,'todos'));for(const [value,label] of items)s.add(new Option(label,value));if([...s.options].some(x=>x.value===old))s.value=old;}
function auditChoices(){const logs=window.getLogsAtividadesDb(),data=F.auditOptions(logs,getUsuariosDb(),modules);options('filtro-log-usuario',data.users.map(u=>[u.key,u.name+(u.login?' (@'+u.login+')':'')]),'Todos os usuários');options('filtro-log-modulo',data.modules.map(m=>[m,m]),'Todos os módulos');}
window.renderTabelaLogsAtividades=function(){try{const tbody=$('tbody-logs-atividades');if(!tbody)return;const rows=F.filterLogs(window.getLogsAtividadesDb(),{user:$('filtro-log-usuario').value,userName:F.auditOptions(window.getLogsAtividadesDb(),getUsuariosDb()).users.find(u=>u.key===$('filtro-log-usuario').value)?.name||'',module:$('filtro-log-modulo').value,text:$('filtro-log-texto').value,start:$('filtro-log-data-ini').value,end:$('filtro-log-data-fim').value});tbody.replaceChildren();if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.textContent='Nenhum registro para os filtros selecionados.';tr.append(td);tbody.append(tr);}for(const l of rows){const tr=document.createElement('tr');for(const value of [(()=>{try{return F.br(l.data)||'Data não informada';}catch{return String(l.data||'Data inválida');}})()+' '+String(l.hora||''),String(l.nomeUsuario||l.nome||l.usuario||'Usuário não informado')+' — '+String(l.perfil||''),l.modulo||'Não informado',l.acao||'Ação não informada']){const td=document.createElement('td');td.className='p-2.5 text-xs';td.textContent=String(value);tr.append(td);}tbody.append(tr);}}catch(e){showToast('Auditoria: '+e.message,'warning');}};
const openAudit=window.abrirModalRegistroAtividades;window.abrirModalRegistroAtividades=function(...args){const r=openAudit.apply(this,args);auditChoices();window.renderTabelaLogsAtividades();return r;};
function feedback(buttonId,messageId){const b=$(buttonId);if(!b)return;const status=document.createElement('p');status.id=messageId;status.className='mf-near-status';status.setAttribute('role','status');b.after(status);const old=b.onclick;b.onclick=()=>{old?.();status.textContent=$('mp-message').textContent;status.scrollIntoView({block:'nearest'});if(buttonId==='mp-holiday-save')showHolidays();};}
function showHolidays(){let list=$('mf-holidays');if(!list){list=document.createElement('div');list.id='mf-holidays';$('mp-holiday-save')?.after(list);}if(!list)return;try{list.replaceChildren();for(const h of MartinsPlanejamento.config(localStorage).holidays.filter(x=>!x.cancelado)){const p=document.createElement('p');p.className='text-xs';p.textContent=F.br(h.data)+' — '+h.nome+' — '+h.localidade;list.append(p);}}catch(e){list.textContent=e.message;}}
const init=()=>{dates();clean();clientActions();feedback('mp-holiday-save','mf-holiday-status');feedback('mp-copy-preview','mf-copy-status');showHolidays();const copy=$('mp-copy-days');if(copy){copy.placeholder='03/11/2026, 04/11/2026';const d=document.createElement('input');d.type='date';d.id='mf-copy-day';d.setAttribute('aria-label','Escolher data de destino');const add=document.createElement('button');add.type='button';add.textContent='Adicionar data de destino';add.onclick=()=>{try{const value=F.br(d.value);if(!value)throw Error('Escolha uma data');copy.value+=(copy.value.trim()?', ':'')+value;}catch(e){$('mp-message').textContent=e.message;}};copy.after(d,add);dateInput(d);}for(const id of ['filtro-log-usuario','filtro-log-modulo'])if($(id))$(id).onchange=window.renderTabelaLogsAtividades;if($('filtro-log-texto'))$('filtro-log-texto').oninput=window.renderTabelaLogsAtividades;};
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
})();

